import json,time,os,boto3
from botocore.config import Config
DEPLOYMENT = '1'
def handler(event, context):
    result={"deployment":DEPLOYMENT,"function_version":context.function_version,"invoked_function_arn":context.invoked_function_arn,"request_id":context.aws_request_id,"event":event,"started_at":time.time()}
    if event.get("marker"):
        boto3.client("sqs",config=Config(connect_timeout=3,read_timeout=5,retries={"total_max_attempts":1})).send_message(QueueUrl=os.environ["MARKER_QUEUE"],MessageBody=json.dumps(result))
    if event.get("sleep"): time.sleep(min(event["sleep"],15))
    if event.get("fail_v1") and DEPLOYMENT=="1": raise RuntimeError("owned-version-one-retry-probe")
    return result

